function requestsTable(rows,kind){if(!rows.length)return empty(t('noRequests'));return `<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('name')}</th><th>${t('class')}</th><th>${kind==='club'?t('club'):t('activity')}</th><th>${t('status')}</th><th>${t('actions')}</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.created.localeCompare(a.created)).map(r=>`<tr><td><strong>${e(r.name)}</strong><div class="meta">${fmtDate(r.created)}</div></td><td>${e(r.className)}</td><td>${e(r.targetName||'—')}</td><td>${statusBadge(kind==='activity'?(r.participationStatus||r.status):r.status)}</td><td><div class="table-actions">${r.status==='pending'?`<button class="btn btn-soft btn-sm" data-req="${e(r.id)}" data-status="approved">${t('approve')}</button><button class="btn btn-outline btn-sm" data-req="${e(r.id)}" data-status="waitlist">${t('wait')}</button>`:''}${kind==='activity'?`<button class="btn btn-primary btn-sm" data-mark="${e(r.id)}" data-markstatus="contributed">✓ ${t('markContributed')}</button><button class="btn btn-outline btn-sm" data-mark="${e(r.id)}" data-markstatus="absent">${t('markAbsent')}</button>`:`<button class="btn btn-danger btn-sm" data-req="${e(r.id)}" data-status="rejected">${t('reject')}</button>`}</div></td></tr>`).join('')}</tbody></table></div>`}
