function action(a){if(a==='admin-login')return showLoginForm();if(a==='refresh-cloud')return loadAdminData().then(()=>render());if(backendConfigured&&!admin&&['refresh-cloud','new-news','new-activity','new-media','new-project','new-log','sync-github','content-json','backup','restore','csv','word','pdf','project-csv','project-word','project-pdf'].includes(a)){toast(t('adminRequired'));return}if(a==='new-news')return contentForm('news');if(a==='new-activity')return contentForm('activity');if(a==='new-media')return mediaForm();if(a==='new-project')return projectForm();if(a==='new-log')return logForm();if(a==='project-csv')return exportProjectCSV();if(a==='project-word')return exportProjectWord();if(a==='project-pdf')return printProjectReport();if(a==='sync-github')return syncGitHub();if(a==='content-json')return exportContent();if(a==='backup')return exportBackup();if(a==='restore'){return $('#restoreFile')?.click()}if(a==='csv')return exportCSV();if(a==='word')return exportWord();if(a==='pdf'){window.print();return}if(a==='reset'){if(confirm(t('resetDemo')+'?')){db=structuredClone(seed);save();render()}}}
function contentForm(kind){const isNews=kind==='news';$('#modalTitle').textContent=isNews?t('newNews'):t('newActivity');let langFields=['ar','fr','en'].map(l=>`<div class="form-field"><label>${l.toUpperCase()} — ${t('addTitle')}</label><input name="title_${l}" required></div>`).join('');let descFields=['ar','fr','en'].map(l=>`<div class="form-field full"><label>${l.toUpperCase()} — ${t('description')}</label><textarea name="desc_${l}" required></textarea></div>`).join('');$('#modalBody').innerHTML=`<form id="contentForm"><div class="form-grid">${langFields}${descFields}${isNews?`<div class="form-field"><label>${t('type')}</label><select name="type"><option value="announcement">${t('announcement')}</option><option value="news">${t('news')}</option></select></div><div class="form-field"><label>${t('date')}</label><input type="date" name="date" value="${today()}" required></div>`:`<div class="form-field"><label>${t('club')}</label><select name="clubId">${db.clubs.map(c=>`<option value="${e(c.id)}">${text(c.title)}</option>`).join('')}</select></div><div class="form-field"><label>${t('eventDate')}</label><input type="date" name="date" required></div>${['ar','fr','en'].map(l=>`<div class="form-field"><label>${l.toUpperCase()} — ${t('location')}</label><input name="location_${l}"></div>`).join('')}`}</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>${t('cancel')}</button><button class="btn btn-primary">${t('publish')}</button></div></form>`;showModal();$('#contentForm').onsubmit=ev=>{ev.preventDefault();let fd=new FormData(ev.currentTarget),localized=k=>({ar:String(fd.get(k+'_ar')).trim(),fr:String(fd.get(k+'_fr')).trim(),en:String(fd.get(k+'_en')).trim()});if(isNews)db.news.unshift({id:'n'+Date.now(),title:localized('title'),body:localized('desc'),date:String(fd.get('date')),type:String(fd.get('type')),category:'school'});else db.activities.push({id:'a'+Date.now(),title:localized('title'),desc:localized('desc'),date:String(fd.get('date')),clubId:String(fd.get('clubId')),icon:'✨',location:{ar:String(fd.get('location_ar')),fr:String(fd.get('location_fr')),en:String(fd.get('location_en'))}});save();closeModal();render();toast(t('published'))}}
function fillReportTargets(){const k=$('#reportKind')?.value,s=$('#reportTarget');if(!s)return;let list=k==='club'?db.clubs:k==='activity'?db.activities:[];s.innerHTML=`<option value="all">${t('all')}</option>`+list.map(x=>`<option value="${e(x.id)}">${text(x.title)}</option>`).join('')}
function mediaForm(){$('#modalTitle').textContent=t('addMedia');$('#modalBody').innerHTML=`<form id="mediaForm"><div class="form-grid"><div class="form-field full"><label>${t('mediaUrl')} *</label><input name="url" type="url" placeholder="https://..." required></div><div class="form-field"><label>${t('mediaType')}</label><select name="type"><option value="photo">${t('photo')}</option><option value="video">${t('video')}</option></select></div><div class="form-field"><label>${t('date')}</label><input type="date" name="date" value="${today()}"></div>${['ar','fr','en'].map(l=>`<div class="form-field"><label>${l.toUpperCase()} — ${t('caption')}</label><input name="caption_${l}"></div>`).join('')}</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>${t('cancel')}</button><button class="btn btn-primary">${t('publish')}</button></div></form>`;showModal();$('#mediaForm').onsubmit=ev=>{ev.preventDefault();let fd=new FormData(ev.currentTarget);db.gallery=db.gallery||[];db.gallery.unshift({id:'m'+Date.now(),url:String(fd.get('url')).trim(),type:String(fd.get('type')),date:String(fd.get('date')||today()),caption:{ar:String(fd.get('caption_ar')),fr:String(fd.get('caption_fr')),en:String(fd.get('caption_en'))}});save();closeModal();render();toast(t('mediaAdded'))}}
async function syncGitHub(){const input=$('#githubUrl'),url=(input?.value||localStorage.getItem('school_github_content_url')||'./content.json').trim();if(input)localStorage.setItem('school_github_content_url',url);try{const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error('http');const data=await res.json();for(const k of ['news','clubs','activities','gallery','projects','logs'])if(Array.isArray(data[k]))db[k]=data[k];save();render();toast(t('syncOk'))}catch{toast(t('syncFail'))}}
function exportContent(){const safeProjects=(db.projects||[]).map(p=>({id:p.id,code:p.code,title:p.title,domain:p.domain,objective:p.objective,audience:p.audience,expectedBeneficiaries:p.expectedBeneficiaries,startDate:p.startDate,endDate:p.endDate,plannedActivities:p.plannedActivities,status:p.status}));const data={version:1,updatedAt:new Date().toISOString(),news:db.news,clubs:db.clubs,activities:db.activities,gallery:db.gallery||[],projects:safeProjects};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),'content.json');toast(t('contentExported'))}
function exportBackup(){const data={version:1,createdAt:new Date().toISOString(),...db};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),`school-hub-backup-${today()}.json`);toast(t('backupDone'))}
function restoreBackup(ev){const f=ev.target.files?.[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{try{const x=JSON.parse(rd.result);if(!Array.isArray(x.news)||!Array.isArray(x.clubs)||!Array.isArray(x.activities)||!Array.isArray(x.requests))throw Error('bad');db={...seed,...x,gallery:Array.isArray(x.gallery)?x.gallery:[],projects:Array.isArray(x.projects)?x.projects:[],logs:Array.isArray(x.logs)?x.logs:[]};save();render();toast(t('restoreDone'))}catch{toast(t('syncFail'))}finally{ev.target.value=''}};rd.readAsText(f)}
function reportRows(){let kind=$('#reportKind')?.value||'all',target=$('#reportTarget')?.value||'all',status=$('#reportStatus')?.value||'all',from=$('#reportFrom')?.value||'',to=$('#reportTo')?.value||'';return db.requests.filter(r=>{let rs=r.kind==='activity'?(r.participationStatus||r.status):r.status;return(kind==='all'||r.kind===kind)&&(target==='all'||r.targetId===target)&&(status==='all'||rs===status)&&(from===''||r.created>=from)&&(to===''||r.created<=to)}).sort((a,b)=>a.created.localeCompare(b.created))}function reportHeaders(){return [t('name'),t('class'),t('type'),t('club')+'/'+t('activity'),t('status'),t('role'),t('submitted'),t('generated')]}function reportData(r){return [r.name,r.className,r.kind==='club'?t('club'):t('activity'),r.targetName,r.kind==='activity'?t(r.participationStatus||r.status):t(r.status),t(r.role||'student'),r.created,t('schoolYear')]}
function exportCSV(){const rows=reportRows();if(!rows.length){toast(t('noData'));return}const data=[reportHeaders(),...rows.map(reportData)],csv='\ufeff'+data.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`school-report-${today()}.csv`)}function exportWord(){const rows=reportRows();if(!rows.length){toast(t('noData'));return}let html=`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#192746}h1{text-align:center;color:#122448}table{width:100%;border-collapse:collapse}th,td{border:1px solid #9aa5b7;padding:8px;text-align:start}th{background:#e7f4f2}.meta{text-align:center;color:#667}</style></head><body><h1>${t('reportTitle')} — ${t('schoolYear')}</h1><p>${t('generated')}: ${fmtDate(today())}</p><table><thead><tr>${reportHeaders().map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${reportData(r).map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="meta">${t('schoolName')} · School Hub</p></body></html>`;download(new Blob(['\ufeff',html],{type:'application/msword;charset=utf-8'}),`school-report-${today()}.doc`)}function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function backendError(err){return err?.code==='23505'?t('cloudDuplicate'):t('cloudError')}
async function cloudUpsert(table,row){if(!supabaseClient)return true;if(!admin){toast(t('adminRequired'));return false}const {error}=await supabaseClient.from(table).upsert(row,{onConflict:'id'});if(error){toast(backendError(error));return false}return true}
async function checkAdminSession(){if(!supabaseClient)return false;const {data:{user}}=await supabaseClient.auth.getUser();if(!user){admin=false;cloudUser=null;return false}const {data,error}=await supabaseClient.from('user_roles').select('role').eq('user_id',user.id).maybeSingle();if(error||!data||data.role!=='admin'){await supabaseClient.auth.signOut();admin=false;cloudUser=null;return false}cloudUser=user;admin=true;return true}
async function loadAdminData(){if(!supabaseClient||!admin)return;const [rq,pr,lg]=await Promise.all([supabaseClient.from('applications').select('*').order('created_at',{ascending:false}),supabaseClient.from('school_projects').select('id,code,payload'),supabaseClient.from('activity_logs').select('id,project_id,activity_date,payload').order('activity_date',{ascending:false})]);if(rq.error){toast(t('cloudError'));return}db.requests=(rq.data||[]).map(x=>({id:x.id,kind:x.kind,targetId:x.target_id,targetName:x.target_name,name:x.full_name,className:x.class_name,reason:x.reason,role:x.participation_type,status:x.status,participationStatus:x.participation_status,created:String(x.created_at).slice(0,10)}));if(!pr.error){const remote=(pr.data||[]).map(x=>x.payload).filter(Boolean),ids=new Set(remote.map(x=>x.id));db.projects=[...remote,...(db.projects||[]).filter(x=>!ids.has(x.id))]}if(!lg.error){const remote=(lg.data||[]).map(x=>x.payload).filter(Boolean),ids=new Set(remote.map(x=>x.id));db.logs=[...remote,...(db.logs||[]).filter(x=>!ids.has(x.id))]}save()}
async function startAdminRealtime(){if(!supabaseClient||!admin)return;if(cloudChannel)await supabaseClient.removeChannel(cloudChannel);cloudChannel=supabaseClient.channel('school-hub-admin').on('postgres_changes',{event:'*',schema:'public',table:'applications'},async()=>{await loadAdminData();if(view==='dashboard'&&!$('#modal').open)render()}).on('postgres_changes',{event:'*',schema:'public',table:'school_projects'},async()=>{await loadAdminData();if(['projects','tracking'].includes(view)&&!$('#modal').open)render()}).on('postgres_changes',{event:'*',schema:'public',table:'activity_logs'},async()=>{await loadAdminData();if(['projects','tracking'].includes(view)&&!$('#modal').open)render()}).subscribe()}
function showLoginForm(){if(!backendConfigured){toast(t('backendMissing'));return}if(!supabaseClient){toast(t('cloudError'));return}$('#modalTitle').textContent=t('adminLogin');$('#modalBody').innerHTML=`<form id="adminLoginForm"><div class="form-grid"><div class="form-field full"><label>${t('email')}</label><input name="email" type="email" autocomplete="username" required></div><div class="form-field full"><label>${t('password')}</label><input name="password" type="password" autocomplete="current-password" required></div></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>${t('cancel')}</button><button class="btn btn-primary">${t('login')}</button></div></form>`;showModal();$('#adminLoginForm').onsubmit=async ev=>{ev.preventDefault();let fd=new FormData(ev.currentTarget);const {error}=await supabaseClient.auth.signInWithPassword({email:String(fd.get('email')).trim(),password:String(fd.get('password'))});if(error){toast(t('loginFailed'));return}if(!await checkAdminSession()){toast(t('notAdmin'));closeModal();return}await loadAdminData();await startAdminRealtime();closeModal();toast(t('loginSuccess'));render()}}
async function roleAction(){if(!backendConfigured){admin=!admin;toast(admin?t('checkRole'):t('studentMode'));if(view==='dashboard'&&!admin)go('home');else render();return}if(!supabaseClient){toast(t('cloudError'));return}if(admin){await supabaseClient.auth.signOut();if(cloudChannel)await supabaseClient.removeChannel(cloudChannel);cloudChannel=null;admin=false;cloudUser=null;render();toast(t('logout'));return}showLoginForm()}
async function initBackend(){if(!backendConfigured)return;if(!window.supabase?.createClient){toast(t('cloudError'));return}try{supabaseClient=window.supabase.createClient(BACKEND_CFG.url,BACKEND_CFG.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});const ok=await checkAdminSession();if(ok){await loadAdminData();await startAdminRealtime();$('#roleBtn').textContent='A';$('#roleBtn').title=t('logout');if(['dashboard','tracking'].includes(view))render()}$('#roleBtn').classList.add('cloud-mode');const sync=$('.sync-state span');if(sync)sync.textContent=t('onlineMode');const dot=$('.sync-state i');if(dot)dot.classList.add('connected')}catch{toast(t('cloudError'))}}
$$('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));$('#mainNav').onclick=ev=>{const b=ev.target.closest('[data-view]');if(b)go(b.dataset.view)};$('#roleBtn').onclick=()=>roleAction();$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#modal').addEventListener('click',ev=>{if(ev.target===ev.currentTarget||ev.target.closest('[data-close]'))closeModal()});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(deferredInstall){deferredInstall.prompt();deferredInstall=null}else toast('Serve via HTTPS to install as a PWA.')};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});setLang(lang);initBackend();if(location.protocol==='https:'||location.protocol==='http:'){const feed=localStorage.getItem('school_github_content_url')||'./content.json';fetch(feed,{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(!data)return;for(const k of ['news','clubs','activities','gallery','projects','logs'])if(Array.isArray(data[k]))db[k]=data[k];save();if(view!=='dashboard')render()}).catch(()=>{})}
